 q('[data-editor-export]').onclick=async()=>{if(jobId||busy)return;try{if(!ready)throw Error('请使用本机视频引擎启动剪辑版');if(project.transparent&&!['vp9','prores'].includes(project.output.codec))throw Error('透明背景请选择 ProRes 4444 或 VP9 Alpha 编码器');seekTo(time);const result=await rpc('export',{project:serialize(),design:structuredClone(state),images:structuredClone(images),fonts:studioFonts.list()});jobId=result.id;q('.studio-editor-export-progress').hidden=false;let job;do{await new Promise(r=>setTimeout(r,800));job=await rpc('job',{id:jobId});q('.studio-editor-export-progress strong').textContent=job.phase==='preparing-media'?'正在准备全尺寸导出素材':job.phase==='preparing-workers'?'正在启动并行合成':job.phase==='encoding'?'正在完成视频编码':'正在逐帧合成与编码';q('progress').value=job.progress;q('[data-progress]').textContent=[Math.round(job.progress*100)+'%',job.encoding,job.pipeline==='sequential'?'连续解码':'',job.workers?job.workers+' 路合成':'',job.fps?'合成 '+job.fps.toFixed(1)+' 帧/秒':'',job.notice||''].filter(Boolean).join(' · ');}while(job.status==='rendering');if(job.status==='complete'){await rpc('download',{url:job.download});report('导出完成 · '+(job.encoding||'视频')+' · 视频已下载。'+(job.notice||''));}else report(job.status==='cancelled'?'导出已取消':job.error,true);}catch(e){report(e.message,true);}finally{jobId=null;q('.studio-editor-export-progress').hidden=true;}};
