  async loadRender(payload){clearTimeout(saveTimer);for(const n of nodes.values())disposeNode(n);nodes.clear();rendering=true;monitoring=false;project=payload.project;await studioFonts.replace(payload.fonts||[]);restore({privateContent:payload.design});Object.assign(images,payload.images);state.playing=false;sync();enter();view.art.classList.add('studio-editor-render-art');root.classList.add('studio-editor-render');document.documentElement.style.setProperty('background','transparent','important');document.body.style.setProperty('background','transparent','important');await document.fonts.ready;rebuild();resize();for(const n of nodes.values())await new Promise((resolve,reject)=>{if(n.asset.kind==='audio'||n.asset.renderFrames)return resolve();if(n.asset.image?n.media.complete:n.media.readyState>=2)return resolve();const timeout=setTimeout(()=>reject(Error('素材加载超时：'+n.asset.name)),60000);n.media.addEventListener(n.asset.image?'load':'loadeddata',()=>{clearTimeout(timeout);resolve();},{once:true});n.media.addEventListener('error',()=>reject(Error('素材加载失败')),{once:true});});await Promise.all([...view.art.querySelectorAll('img')].map(img=>img.complete?Promise.resolve():img.decode().catch(()=>{})));},
